  (* [comment removed for export] *)
  Lemma ie_fast : forall (cnt i : nat) m1 j8 (w8 w16 : word) (A0 LA LB : list Z) (lastn : Z) (dl : elt)
      (x1 x5 x6 x7 a0x a7 x28 x29 x30 x31 : word),
    IEM m1 j8 w8 w16 ->
    ubA = A0 ++ [lastn] -> L = LA ++ (lastn - 16) :: LB -> em !! (lastn - 16) = Some dl ->
